mapper.select:


    user1.deleted_flag = 'N'
    and user1.id != #{userId}
    and user1.remark like concat('%', #{remark}, '%')
    and user1.login_name = #{loginName}
    and user1.nick_name like concat('%', #{nickName}, '%')
    and user1.user_type = #{userType}
    and user1.email = #{email}
    and user1.phone = #{phone}
    and user1.password = #{password}
    and user1.gender = #{gender}
    and user1.avatar = #{avatar}
    and user1.status = #{status}
    and user1.identity_num = #{identityNum}
    and user1.organization_id = #{organizationId}


        and

            user1.department_id = #{item}




        and

            (
            user1.nick_name like concat('%', #{item}, '%')
            or user1.remark like concat('%', #{item}, '%')
            or user1.login_name like concat('%', #{item}, '%')
            )



order by user1.created_time desc

select user1.id, user1.remark, user1.login_name, user1.nick_name, user1.user_type, user1.email, user1.phone, user1.gender, user1.avatar, user1.status, user1.identity_num, user1.organization_id, user1.department_id from system_user_base as user1
id in
#{userId}

select distinct user1.id, user1.remark, user1.login_name, user1.nick_name, user1.user_type, user1.email, user1.phone, user1.gender, user1.avatar, user1.status, user1.identity_num, user1.organization_id, user1.department_id from system_user_base as user1
user1.deleted_flag = 'N' and user1.status = 1 and user1.department_id in
#{deptId}

select distinct user1.id, user1.remark, user1.login_name, user1.nick_name, user1.user_type, user1.email, user1.phone, user1.gender, user1.avatar, user1.status, user1.identity_num, user1.organization_id, user1.department_id from system_user_base as user1 left join system_user_group_user as userGroupUser on userGroupUser.user_id = user1.id left join system_user_group as userGroup on userGroupUser.group_id = userGroup.id and userGroup.status = 1
user1.deleted_flag = 'N' and user1.status = 1 and userGroupUser.deleted_flag = 'N' and userGroup.deleted_flag = 'N'
and user1.department_id = #{departmentId}
and userGroupUser.group_id in
#{groupId}

select distinct user1.id, user1.remark, user1.login_name, user1.nick_name, user1.user_type, user1.email, user1.phone, user1.gender, user1.avatar, user1.status, user1.identity_num, user1.organization_id, user1.department_id from system_user_base as user1 left join system_role_user as roleUser on roleUser.user_id = user1.id left join system_role as role on role.id = roleUser.role_id and role.status = 1 left join system_role_user_dept as roleUserDept on roleUserDept.role_user_id = roleUser.id
user1.deleted_flag = 'N' and user1.status = 1 and role.deleted_flag = 'N' and roleUser.deleted_flag = 'N' and ( roleUserDept.deleted_flag = 'N' or roleUserDept.deleted_flag is null) and role.organization_id = #{organizationId} and ( role.department_id = #{departmentId} or (user1.department_id = #{departmentId} or roleUserDept.department_id = #{departmentId} ) ) and role.role_key in
#{code}

select distinct user1.id, user1.remark, user1.login_name, user1.nick_name, user1.user_type, user1.email, user1.phone,
user1.gender, user1.avatar, user1.status, user1.identity_num, user1.organization_id, user1.department_id
from system_user_base as user1
left join system_user_group_user as userGroupUser on userGroupUser.user_id = user1.id
left join system_user_group as userGroup on userGroupUser.group_id = userGroup.id and userGroup.status = 1


    user1.deleted_flag = 'N' and user1.status = 1 and userGroup.deleted_flag = 'N' and userGroupUser.deleted_flag = 'N'
    and userGroup.organization_id = #{organizationId}
    and userGroup.department_id = #{departmentId}
    and userGroup.group_code in

        #{code}

select user1.created_by, user1.created_time, user1.id, user1.remark, user1.login_name, user1.nick_name, user1.user_type, user1.email, user1.phone, user1.gender, user1.avatar, user1.status, user1.identity_num, social.uid as third_account, social.open_id as open_id, social.union_id as third_union_id,
serorg.organization_id, serorg.department_id, org.organization_name from system_user_service_org serorg left join system_user_base as user1 on serorg.user_id = user1.id left join system_organization org on org.id = serorg.organization_id left join system_user_social_user socialUser on socialUser.user_id = user1.id and socialUser.deleted_flag = 'N' left join system_social_user social on social.id = socialUser.social_user_id and social.deleted_flag = 'N'
user1.deleted_flag = 'N' and serorg.deleted_flag = 'N' and org.deleted_flag = 'N'
and social.open_id = #{openId}
and user1.phone = #{phone}

select user1.created_by, user1.created_time, user1.updated_by, user1.updated_time, user1.id, user1.remark, user1.login_name, user1.nick_name, user1.user_type, user1.email, user1.phone, user1.password, user1.gender, user1.avatar, user1.status, user1.identity_num, user1.organization_id, user1.department_id, org.organization_name from system_user_base as user1 left join system_organization org on org.id = user1.organization_id
user1.organization_id = #{organizationId} and user1.deleted_flag = 'N'
and user1.department_id = #{departmentId}
